public class Main {
  static int[] w;
  static int daysNeeded(long cap) { int days = 1; long load = 0; for (int x : w) { if (load + x > cap) { days++; load = 0; } load += x; } return days; }
  public static void main(String[] args) throws IOException {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
